# hypothesis check: does the transformation preserve per-column counts after shifting?
def percol_shift(m, out):
    # find shift per column using majority
    H=len(m); W=len(m[0])
    shifts={}
    for c in range(W):
        rs=[r for r in range(H) if m[r][c]]
        rs2=[r for r in range(H) if out[r][c]]
        if rs and rs2:
            diffs=[b-a for a,b in zip(sorted(rs),sorted(rs2))]
            shifts[c]=max(diffs,key=diffs.count)
        else:
            shifts[c]=None
    return shifts
