def comps(g):
    g=np.array(g); H,W=g.shape; lab=-np.ones((H,W)); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and lab[r][c]<0:
                col=int(g[r][c]); st=[(r,c)]; cells=[]; lab[r][c]=0
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and lab[ny][nx]<0:
                            lab[ny][nx]=0; st.append((ny,nx))
                res.append(cells)
    return g,res
