    for r in range(h):
        for c in range(w):
            if g[r,c]!=0 and not visited[r,c]:
                cells=[(r,c)]; vis={r,c}; 
                while True:
                    nxt=[]
                    for rr,cc in cells:
                        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                            n=(rr+dr,cc+dc)
                            if n[0]<h and n[1]<w and g[n]==g[r,c] and not visited[n]:
                                visited[n]=True; nxt.append(n)
                    if not nxt: break
                    cells=nxt
                # drop so min row -> 0
                rs=[p[0] for p in cells]; dr=min(rs)
                for r_,c_ in cells:
                    out[r_-dr+r_, c_]=g[r_,c_]
    return out
